      /* (568) call_arguments ::= */ yytestcase(yyruleno==568);
      /* (605) flush_table_tail ::= */ yytestcase(yyruleno==605);
      /* (658) table_query_tail ::= */ yytestcase(yyruleno==658);
      /* (661) table_offset_tail ::= */ yytestcase(yyruleno==661);
      /* (666) values_row_contents ::= */ yytestcase(yyruleno==666);
      /* (677) values_query_tail ::= */ yytestcase(yyruleno==677);
      /* (682) execute_tail ::= */ yytestcase(yyruleno==682);
      /* (705) signal_set_tail ::= */ yytestcase(yyruleno==705);
      /* (707) transaction_end_tail ::= */ yytestcase(yyruleno==707);
      /* (805) resignal_tail ::= */ yytestcase(yyruleno==805);
      /* (815) statement_tail ::= */ yytestcase(yyruleno==815);
        break;
